from collections import Counter

def transform(grid):
    # Each 3x3 patch encodes one color. Ignore the grid's dominant
    # background color, then select the most frequent remaining color.
    background = Counter(value for row in grid for value in row).most_common(1)[0][0]
    out = []
    for r in range(0, len(grid), 3):
        row = []
        for c in range(0, len(grid[0]), 3):
            patch = [grid[i][j] for i in range(r, min(r + 3, len(grid)))
                     for j in range(c, min(c + 3, len(grid[0])))
                     if grid[i][j] != background]
            if patch:
                counts = Counter(patch)
                row.append(max(counts, key=counts.get))
            else:
                row.append(background)
        out.append(row)
    return out

